def changed_paths(before, after):
    """Return sorted dot-separated paths for additions, removals, or unequal leaves.

    Recurses only where BOTH values are dictionaries.
    Treats lists (and all non-dict values) atomically.
    If an entire dictionary key is added/removed, only the parent path is returned.
    """
    changes = set()

    def _compare(b, a, prefix):
        for key in b.keys() | a.keys():
            path = f"{prefix}.{key}" if prefix else key
            if key not in b:
                changes.add(path)
            elif key not in a:
                changes.add(path)
            else:
                bv, av = b[key], a[key]
                if isinstance(bv, dict) and isinstance(av, dict):
                    _compare(bv, av, path)
                elif bv != av:
                    changes.add(path)

    _compare(before, after, "")
    return sorted(changes)
```

