def frames(lines):
    data_fields = []
    for line in lines:
        if line == "":
            if data_fields:
                yield "\n".join(data_fields)
            data_fields = []
        elif line.startswith(":"):
            continue
        else:
            if ":" in line:
                field_name, value = line.split(":", 1)
            else:
                field_name, value = line, ""
            if field_name == "data":
                if value.startswith(" "):
                    value = value[1:]
                data_fields.append(value)
    # final event without blank-line terminator is discarded
