from copy import deepcopy


def merge(base, overlay):
    """Recursively merge two JSON-like dictionaries into a deep-independent result.

    Overlay values replace base values. Nested dicts are merged recursively;
    all other values (lists, scalars, None) are replaced wholesale.
    A None value in overlay does not delete the key.
    Neither input is mutated; the result shares no nested references with them.
    """
    result = {}

    for key, base_val in base.items():
        if key in overlay:
            overlay_val = overlay[key]
            if isinstance(base_val, dict) and isinstance(overlay_val, dict):
                result[key] = merge(base_val, overlay_val)
            else:
                result[key] = deepcopy(overlay_val)
        else:
            result[key] = deepcopy(base_val)

    for key, overlay_val in overlay.items():
        if key not in base:
            result[key] = deepcopy(overlay_val)

    return result
```

