    """Flatten a nested dictionary with string keys into dot-separated keys.

    - Nested non-empty dicts are recursively flattened with '.' as separator.
    - Empty dict leaves are represented as {} at their path.
    - Lists and scalars are preserved as-is (leaf values).
    - An empty root dict produces {}.
    - The input is not mutated.
    """
    if not isinstance(value, dict):
        raise TypeError(f"expected a dict, got {type(value).__name__}")

    if not value:
        return {}

    result = {}
    for key, val in value.items():
        if isinstance(val, dict) and val:
            for sub_key, sub_val in flatten(val).items():
                result[f"{key}.{sub_key}"] = sub_val
        elif isinstance(val, dict):
            result[key] = {}
        else:
            result[key] = val
    return result
