def normalize(path: str) -> str:
    """Normalize an absolute POSIX-like path.

    Rules:
      - Must be absolute (start with '/'); raises ValueError otherwise.
      - Collapses repeated '/'.
      - Ignores '.' components.
      - Resolves '..' without going above root.
      - Returns '/' for the root.
      - Never returns a trailing slash (except the root itself).
    """
    if not isinstance(path, str) or not path.startswith("/"):
        raise ValueError(f"Expected an absolute POSIX path, got: {path!r}")

    parts = path.split("/")
    stack: list[str] = []

    for part in parts:
        if part == "" or part == ".":
            continue
        if part == "..":
            if stack:
                stack.pop()
            # else: already at root, ignore
        else:
            stack.append(part)

    if not stack:
        return "/"
    return "/" + "/".join(stack)
```

