def pack(items, max_bytes):
    if max_bytes < 1:
        raise ValueError("max_bytes must be >= 1")

    for item in items:
        if len(item.encode("utf-8")) > max_bytes:
            raise ValueError(f"item does not fit within max_bytes: {item!r}")

    if not items:
        return []

    result = []
    current_batch = []
    current_bytes = 0

    for item in items:
        item_bytes = len(item.encode("utf-8"))
        if current_batch and current_bytes + item_bytes > max_bytes:
            result.append(current_batch)
            current_batch = []
            current_bytes = 0
        current_batch.append(item)
        current_bytes += item_bytes

    if current_batch:
        result.append(current_batch)

    return result
```

