from collections import deque

def admit(times, limit, window):
    if limit < 1 or window < 1:
        raise ValueError
    result = []
    dq = deque()
    for t in times:
        while dq and dq[0] <= t - window:
            dq.popleft()
        if len(dq) < limit:
            dq.append(t)
            result.append(True)
        else:
            result.append(False)
    return result
