import heapq


def order(deps):
    # Collect all nodes (keys + all prerequisite values)
    nodes = set(deps.keys())
    for prereqs in deps.values():
        nodes.update(prereqs)

    # Build reverse adjacency: for each node, which nodes list it as a prerequisite
    dependents = {node: [] for node in nodes}
    for node, prereqs in deps.items():
        for p in prereqs:
            dependents[p].append(node)

    # In-degree = number of prerequisites for each node
    in_degree = {}
    for node in nodes:
        in_degree[node] = len(deps[node]) if node in deps else 0

    # Min-heap seeded with all currently ready (in-degree 0) nodes
    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dep in dependents[node]:
            in_degree[dep] -= 1
            if in_degree[dep] == 0:
                heapq.heappush(heap, dep)

    if len(result) != len(nodes):
        raise ValueError("cycle detected")

    return result
```

